// lib/router/app_router.dart

import 'package:go_router/go_router.dart';
import 'package:flutter/material.dart';

// Импортируем наши экраны
import '../screens/home_screen.dart';
import '../screens/profile_screen.dart';
import '../screens/settings_screen.dart';

// Создаём роутер
final GoRouter appRouter = GoRouter(
  // Начальный маршрут
  initialLocation: '/',

  // Включить отладочные логи (для разработки)
  debugLogDiagnostics: true,

  // Список маршрутов
  routes: [
    // Главная страница
    GoRoute(
      path: '/',
      name: 'home',
      builder: (context, state) => const HomeScreen(),
    ),

    // Страница профиля
    GoRoute(
      path: '/profile',
      name: 'profile',
      builder: (context, state) => const ProfileScreen(),
    ),

    // Страница настроек
    GoRoute(
      path: '/settings',
      name: 'settings',
      builder: (context, state) => const SettingsScreen(),
    ),
  ],
);

import 'package:flutter/material.dart';
import 'package:go_router/go_router.dart';

class HomeScreen extends StatelessWidget {
  const HomeScreen({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Главная'),
      ),
      body: Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            // Кнопка перехода на профиль
            ElevatedButton(
              onPressed: () {
                // Переходим на страницу профиля
                context.go('/profile');
              },
              child: const Text('Открыть профиль'),
            ),

            const SizedBox(height: 16),

            // Кнопка с push (добавляет в стек)
            ElevatedButton(
              onPressed: () {
                // Добавляем страницу в стек
                context.push('/settings');
              },
              child: const Text('Настройки (push)'),
            ),

            const SizedBox(height: 16),

            // Навигация по имени
            ElevatedButton(
              onPressed: () {
                context.goNamed('profile');
              },
              child: const Text('Профиль (по имени)'),
            ),
          ],
        ),
      ),
    );
  }
}

